        [7.113d1,2.765d2,1.439d4,1.347d5,2.496d5,2.204d6,0d0,0d0,0d0])

   type(rec_fit), parameter :: bad_OI  = rec_fit(                         &
        6.622d-11, 0.6109d0, 4.136d0, 4.214d6, 0.4093d0, 8.770d4, 4,      &
