   type(rec_fit), parameter :: bad_MgII = rec_fit(                        &
        1.345d-11, 0.1074d0, 7.877d2, 7.925d7, 0.4631d0, 5.027d5, 3,      &
        [6.269d-6,9.181d-4,3.082d-4,0d0,0d0,0d0,0d0,0d0,0d0],             &
