        1.964d-10, 0.6287d0, 7.712d0, 2.951d7, 0.1523d0, 4.804d5, 5,      &
        [2.930d-6,2.803d-6,9.023d-5,6.909d-3,2.582d-5,0d0,0d0,0d0,0d0],   &
        [1.162d2,5.721d3,3.477d4,1.176d5,3.505d6,0d0,0d0,0d0,0d0])

