   subroutine cool_OI_range(T,coeff_cool_OI,j_lo,j_hi)
   integer, intent(in) :: j_lo,j_hi
   real*8, dimension(1-Ng:N+Ng), intent(in) :: T
   real*8, dimension(1-Ng:N+Ng), intent(inout) :: coeff_cool_OI
