   real*8, dimension(1-Ng:N+Ng), intent(inout) :: coeff_cool_MgI
   coeff_cool_MgI(j_lo:j_hi) = cool_MgI_func(T(j_lo:j_hi))
   end subroutine cool_MgI_range


